def _tokens(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise KeyError(pointer)
    return [t.replace("~1", "/").replace("~0", "~") for t in pointer[1:].split("/")]


def _valid_index(token):
    # A list index must be decimal digits with no leading zeros (RFC 6901).
    if not token or not token.isdigit():
        return None
    if len(token) > 1 and token[0] == "0":
        return None
    try:
        return int(token)
    except ValueError:
        return None


def _step(node, token):
    if isinstance(node, list):
        idx = _valid_index(token)
        if idx is None or idx >= len(node):
            raise KeyError(token)
        return node[idx]
    if isinstance(node, dict):
        if token in node:
            return node[token]
        raise KeyError(token)
    raise KeyError(token)


def resolve(doc, pointer):
    node = doc
    for token in _tokens(pointer):
        node = _step(node, token)
    return node


def set_at(doc, pointer, value):
    tokens = _tokens(pointer)
    if not tokens:
        raise KeyError(pointer)
    node = doc
    for token in tokens[:-1]:
        node = _step(node, token)
    last = tokens[-1]
    if isinstance(node, list):
        if last == "-":
            node.append(value)
            return None
        idx = _valid_index(last)
        if idx is None or idx >= len(node):
            raise KeyError(last)
        node[idx] = value
        return None
    if isinstance(node, dict):
        node[last] = value
        return None
    raise KeyError(last)

